    Cluster.add_member(:pending_tasks_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'pendingTasksCount', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of tasks in the cluster that are in the <code>PENDING</code> state.</p>"}))
    Cluster.add_member(:active_services_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'activeServicesCount', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of services that are running on the cluster in an <code>ACTIVE</code>\n\t\t\tstate. You can view these services with <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_ListServices.html\">PListServices</a>.</p>"}))
    Cluster.add_member(:statistics, Smithy::Schema::Shapes::ShapeRef.new(shape: Statistics, location_name: 'statistics', traits: {"smithy.api#documentation" => "<p>Additional information about your clusters that are separated by launch type. They\n\t\t\tinclude the following:</p>\n         <ul>\n            <li>\n               <p>runningEC2TasksCount</p>\n            </li>\n            <li>\n               <p>RunningFargateTasksCount</p>\n            </li>\n            <li>\n               <p>pendingEC2TasksCount</p>\n            </li>\n            <li>\n               <p>pendingFargateTasksCount</p>\n            </li>\n            <li>\n               <p>activeEC2ServiceCount</p>\n            </li>\n            <li>\n               <p>activeFargateServiceCount</p>\n            </li>\n            <li>\n               <p>drainingEC2ServiceCount</p>\n            </li>\n            <li>\n               <p>drainingFargateServiceCount</p>\n            </li>\n         </ul>"}))
    Cluster.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The metadata that you apply to the cluster to help you categorize and organize them.\n\t\t\tEach tag consists of a key and an optional value. You define both.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only\n                    one value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources,\n                    remember that other services may have restrictions on allowed characters.\n                    Generally allowed characters are: letters, numbers, and spaces representable in\n                    UTF-8, and the following characters: + - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case-sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase\n                    combination of such as a prefix for either keys or values as it is reserved for\n                    Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with\n                    this prefix do not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    Cluster.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterSettings, location_name: 'settings', traits: {"smithy.api#documentation" => "<p>The settings for the cluster. This parameter indicates whether CloudWatch Container Insights\n\t\t\tis on or off for a cluster.</p>"}))
    Cluster.add_member(:capacity_providers, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'capacityProviders', traits: {"smithy.api#documentation" => "<p>The capacity providers associated with the cluster.</p>"}))
    Cluster.add_member(:default_capacity_provider_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityProviderStrategy, location_name: 'defaultCapacityProviderStrategy', traits: {"smithy.api#documentation" => "<p>The default capacity provider strategy for the cluster. When services or tasks are run\n\t\t\tin the cluster with no launch type or capacity provider strategy specified, the default\n\t\t\tcapacity provider strategy is used.</p>"}))
    Cluster.add_member(:attachments, Smithy::Schema::Shapes::ShapeRef.new(shape: Attachments, location_name: 'attachments', traits: {"smithy.api#documentation" => "<p>The resources attached to a cluster. When using a capacity provider with a cluster,\n\t\t\tthe capacity provider and associated resources are returned as cluster\n\t\t\tattachments.</p>"}))
    Cluster.add_member(:attachments_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'attachmentsStatus', traits: {"smithy.api#documentation" => "<p>The status of the capacity providers associated with the cluster. The following are\n\t\t\tthe states that are returned.</p>\n         <dl>\n            <dt>UPDATE_IN_PROGRESS</dt>\n            <dd>\n               <p>The available capacity providers for the cluster are updating.</p>\n            </dd>\n            <dt>UPDATE_COMPLETE</dt>\n            <dd>\n               <p>The capacity providers have successfully updated.</p>\n            </dd>\n            <dt>UPDATE_FAILED</dt>\n            <dd>\n               <p>The capacity provider updates failed.</p>\n            </dd>\n         </dl>"}))
    Cluster.add_member(:service_connect_defaults, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterServiceConnectDefaults, location_name: 'serviceConnectDefaults', traits: {"smithy.api#documentation" => "<p>Use this parameter to set a default Service Connect namespace. After you set a default \n\tService Connect namespace, any new services with Service Connect turned on that are created in the cluster are added as\n\tclient services in the namespace. This setting only applies to new services that set the <code>enabled</code> parameter to\n\t<code>true</code> in the <code>ServiceConnectConfiguration</code>.\n\tYou can set the namespace of each service individually in the <code>ServiceConnectConfiguration</code> to override this default\n\tparameter.</p>\n         <p>Tasks that run in a namespace can use short names to connect\n\tto services in the namespace. Tasks can connect to services across all of the clusters in the namespace.\n\tTasks connect through a managed proxy container\n\tthat collects logs and metrics for increased visibility.\n\tOnly the tasks that Amazon ECS services create are supported with Service Connect.\n\tFor more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-connect.html\">Service Connect</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
