    Container.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'image', traits: {"smithy.api#documentation" => "<p>The image used for the container.</p>"}))
    Container.add_member(:image_digest, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'imageDigest', traits: {"smithy.api#documentation" => "<p>The container image manifest digest.</p>"}))
    Container.add_member(:runtime_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'runtimeId', traits: {"smithy.api#documentation" => "<p>The ID of the Docker container.</p>"}))
    Container.add_member(:last_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'lastStatus', traits: {"smithy.api#documentation" => "<p>The last known status of the container.</p>"}))
    Container.add_member(:exit_code, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'exitCode', traits: {"smithy.api#documentation" => "<p>The exit code returned from the container.</p>"}))
    Container.add_member(:reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'reason', traits: {"smithy.api#documentation" => "<p>A short (1024 max characters) human-readable string to provide additional details about a\n\t\t\trunning or stopped container.</p>"}))
    Container.add_member(:network_bindings, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkBindings, location_name: 'networkBindings', traits: {"smithy.api#documentation" => "<p>The network bindings associated with the container.</p>"}))
    Container.add_member(:network_interfaces, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkInterfaces, location_name: 'networkInterfaces', traits: {"smithy.api#documentation" => "<p>The network interfaces associated with the container.</p>"}))
    Container.add_member(:health_status, Smithy::Schema::Shapes::ShapeRef.new(shape: HealthStatus, location_name: 'healthStatus', traits: {"smithy.api#documentation" => "<p>The health status of the container. If health checks aren't configured for this\n\t\t\tcontainer in its task definition, then it reports the health status as\n\t\t\t\t<code>UNKNOWN</code>.</p>"}))
    Container.add_member(:managed_agents, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedAgents, location_name: 'managedAgents', traits: {"smithy.api#documentation" => "<p>The details of any Amazon ECS managed agents associated with the container.</p>"}))
    Container.add_member(:cpu, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'cpu', traits: {"smithy.api#documentation" => "<p>The number of CPU units set for the container. The value is <code>0</code> if no value\n\t\t\twas specified in the container definition when the task definition was\n\t\t\tregistered.</p>"}))
    Container.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'memory', traits: {"smithy.api#documentation" => "<p>The hard limit (in MiB) of memory set for the container.</p>"}))
    Container.add_member(:memory_reservation, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'memoryReservation', traits: {"smithy.api#documentation" => "<p>The soft limit (in MiB) of memory set for the container.</p>"}))
    Container.add_member(:gpu_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: GpuIds, location_name: 'gpuIds', traits: {"smithy.api#documentation" => "<p>The IDs of each GPU assigned to the container.</p>"}))
