    ContainerOverride.add_member(:command, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'command', traits: {"smithy.api#documentation" => "<p>The command to send to the container that overrides the default command from the\n\t\t\tDocker image or the task definition. You must also specify a container name.</p>"}))
    ContainerOverride.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentVariables, location_name: 'environment', traits: {"smithy.api#documentation" => "<p>The environment variables to send to the container. You can add new environment\n\t\t\tvariables, which are added to the container at launch, or you can override the existing\n\t\t\tenvironment variables from the Docker image or the task definition. You must also\n\t\t\tspecify a container name.</p>"}))
