    ContainerOverride.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'memory', traits: {"smithy.api#documentation" => "<p>The hard limit (in MiB) of memory to present to the container, instead of the default\n\t\t\tvalue from the task definition. If your container attempts to exceed the memory\n\t\t\tspecified here, the container is killed. You must also specify a container name.</p>"}))
