    ContainerRestartPolicy.add_member(:ignored_exit_codes, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerList, location_name: 'ignoredExitCodes', traits: {"smithy.api#documentation" => "<p>A list of exit codes that Amazon ECS will ignore and not attempt a restart on. You can\n\t\t\tspecify a maximum of 50 container exit codes. By default, Amazon ECS does not ignore any exit\n\t\t\tcodes.</p>"}))
    ContainerRestartPolicy.add_member(:restart_attempt_period, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'restartAttemptPeriod', traits: {"smithy.api#documentation" => "<p>A period of time (in seconds) that the container must run for before a restart can be\n\t\t\tattempted. A container can be restarted only once every\n\t\t\t\t<code>restartAttemptPeriod</code> seconds. If a container isn't able to run for this\n\t\t\ttime period and exits early, it will not be restarted. You can set a minimum\n\t\t\t\t<code>restartAttemptPeriod</code> of 60 seconds and a maximum\n\t\t\t\t<code>restartAttemptPeriod</code> of 1800 seconds. By default, a container must run\n\t\t\tfor 300 seconds before it can be restarted.</p>"}))
