    CreateTaskSetRequest.add_member(:external_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'externalId', traits: {"smithy.api#documentation" => "<p>An optional non-unique tag that identifies this task set in external systems. If the\n\t\t\ttask set is associated with a service discovery registry, the tasks in this task set\n\t\t\twill have the <code>ECS_TASK_SET_EXTERNAL_ID</code> Cloud Map attribute set to the provided\n\t\t\tvalue.</p>"}))
    CreateTaskSetRequest.add_member(:task_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskDefinition', traits: {"smithy.api#documentation" => "<p>The task definition for the tasks in the task set to use. If a revision isn't\n\t\t\tspecified, the latest <code>ACTIVE</code> revision is used.</p>", "smithy.api#required" => {}}))
    CreateTaskSetRequest.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>An object representing the network configuration for a task set.</p>"}))
    CreateTaskSetRequest.add_member(:load_balancers, Smithy::Schema::Shapes::ShapeRef.new(shape: LoadBalancers, location_name: 'loadBalancers', traits: {"smithy.api#documentation" => "<p>A load balancer object representing the load balancer to use with the task set. The\n\t\t\tsupported load balancer types are either an Application Load Balancer or a Network Load Balancer.</p>"}))
    CreateTaskSetRequest.add_member(:service_registries, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceRegistries, location_name: 'serviceRegistries', traits: {"smithy.api#documentation" => "<p>The details of the service discovery registries to assign to this task set. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-discovery.html\">Service\n\t\t\t\tdiscovery</a>.</p>"}))
    CreateTaskSetRequest.add_member(:launch_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchType, location_name: 'launchType', traits: {"smithy.api#documentation" => "<p>The launch type that new tasks in the task set uses. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/launch_types.html\">Amazon ECS\n\t\t\t\tlaunch types</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <p>If a <code>launchType</code> is specified, the <code>capacityProviderStrategy</code>\n\t\t\tparameter must be omitted.</p>"}))
    CreateTaskSetRequest.add_member(:capacity_provider_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityProviderStrategy, location_name: 'capacityProviderStrategy', traits: {"smithy.api#documentation" => "<p>The capacity provider strategy to use for the task set.</p>\n         <p>A capacity provider strategy consists of one or more capacity providers along with the\n\t\t\t\t<code>base</code> and <code>weight</code> to assign to them. A capacity provider\n\t\t\tmust be associated with the cluster to be used in a capacity provider strategy. The\n\t\t\t\t<a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_PutClusterCapacityProviders.html\">PutClusterCapacityProviders</a> API is used to associate a capacity provider\n\t\t\twith a cluster. Only capacity providers with an <code>ACTIVE</code> or\n\t\t\t\t<code>UPDATING</code> status can be used.</p>\n         <p>If a <code>capacityProviderStrategy</code> is specified, the <code>launchType</code>\n\t\t\tparameter must be omitted. If no <code>capacityProviderStrategy</code> or\n\t\t\t\t<code>launchType</code> is specified, the\n\t\t\t\t<code>defaultCapacityProviderStrategy</code> for the cluster is used.</p>\n         <p>If specifying a capacity provider that uses an Auto Scaling group, the capacity\n\t\t\tprovider must already be created. New capacity providers can be created with the <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_CreateCapacityProviderProvider.html\">CreateCapacityProviderProvider</a>API operation.</p>\n         <p>To use a Fargate capacity provider, specify either the <code>FARGATE</code> or\n\t\t\t\t<code>FARGATE_SPOT</code> capacity providers. The Fargate capacity providers are\n\t\t\tavailable to all accounts and only need to be associated with a cluster to be\n\t\t\tused.</p>\n         <p>The <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_PutClusterCapacityProviders.html\">PutClusterCapacityProviders</a> API operation is used to update the list of\n\t\t\tavailable capacity providers for a cluster after the cluster is created.</p>"}))
    CreateTaskSetRequest.add_member(:platform_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'platformVersion', traits: {"smithy.api#documentation" => "<p>The platform version that the tasks in the task set uses. A platform version is\n\t\t\tspecified only for tasks using the Fargate launch type. If one isn't\n\t\t\tspecified, the <code>LATEST</code> platform version is used.</p>"}))
    CreateTaskSetRequest.add_member(:scale, Smithy::Schema::Shapes::ShapeRef.new(shape: Scale, location_name: 'scale', traits: {"smithy.api#documentation" => "<p>A floating-point percentage of the desired number of tasks to place and keep running\n\t\t\tin the task set.</p>"}))
    CreateTaskSetRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientToken', traits: {"smithy.api#documentation" => "<p>An identifier that you provide to ensure the idempotency of the request. It must be\n\t\t\tunique and is case sensitive. Up to 36 ASCII characters in the range of 33-126 (inclusive) are allowed.</p>"}))
    CreateTaskSetRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The metadata that you apply to the task set to help you categorize and organize them.\n\t\t\tEach tag consists of a key and an optional value. You define both. When a service is\n\t\t\tdeleted, the tags are deleted.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only\n                    one value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources,\n                    remember that other services may have restrictions on allowed characters.\n                    Generally allowed characters are: letters, numbers, and spaces representable in\n                    UTF-8, and the following characters: + - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case-sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase\n                    combination of such as a prefix for either keys or values as it is reserved for\n                    Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with\n                    this prefix do not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    CreateTaskSetRequest.type = Types::CreateTaskSetRequest
    CreateTaskSetResponse.add_member(:task_set, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskSet, location_name: 'taskSet', traits: {"smithy.api#documentation" => "<p>Information about a set of Amazon ECS tasks in either an CodeDeploy or an\n\t\t\t\t<code>EXTERNAL</code> deployment. A task set includes details such as the desired\n\t\t\tnumber of tasks, how many tasks are running, and whether the task set serves production\n\t\t\ttraffic.</p>"}))
