    DeregisterContainerInstanceRequest.add_member(:container_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'containerInstance', traits: {"smithy.api#documentation" => "<p>The container instance ID or full ARN of the container instance to deregister. For\n\t\t\tmore information about the ARN format, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-account-settings.html#ecs-resource-ids\">Amazon Resource Name (ARN)</a> in the <i>Amazon ECS Developer Guide</i>.</p>", "smithy.api#required" => {}}))
    DeregisterContainerInstanceRequest.add_member(:force, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'force', traits: {"smithy.api#documentation" => "<p>Forces the container instance to be deregistered. If you have tasks running on the\n\t\t\tcontainer instance when you deregister it with the <code>force</code> option, these\n\t\t\ttasks remain running until you terminate the instance or the tasks stop through some\n\t\t\tother means, but they're orphaned (no longer monitored or accounted for by Amazon ECS). If an\n\t\t\torphaned task on your container instance is part of an Amazon ECS service, then the service\n\t\t\tscheduler starts another copy of that task, on a different container instance if\n\t\t\tpossible. </p>\n         <p>Any containers in orphaned service tasks that are registered with a Classic Load Balancer or an Application Load Balancer\n\t\t\ttarget group are deregistered. They begin connection draining according to the settings\n\t\t\ton the load balancer or target group.</p>"}))
