    DescribeCapacityProvidersRequest.add_member(:include, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityProviderFieldList, location_name: 'include', traits: {"smithy.api#documentation" => "<p>Specifies whether or not you want to see the resource tags for the capacity provider.\n\t\t\tIf <code>TAGS</code> is specified, the tags are included in the response. If this field\n\t\t\tis omitted, tags aren't included in the response.</p>"}))
    DescribeCapacityProvidersRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'maxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of account setting results returned by\n\t\t\t\t<code>DescribeCapacityProviders</code> in paginated output. When this parameter is\n\t\t\tused, <code>DescribeCapacityProviders</code> only returns <code>maxResults</code>\n\t\t\tresults in a single page along with a <code>nextToken</code> response element. The\n\t\t\tremaining results of the initial request can be seen by sending another\n\t\t\t\t<code>DescribeCapacityProviders</code> request with the returned\n\t\t\t\t<code>nextToken</code> value. This value can be between\n\t\t\t1 and 10. If this\n\t\t\tparameter is not used, then <code>DescribeCapacityProviders</code> returns up to\n\t\t\t10 results and a <code>nextToken</code> value\n\t\t\tif applicable.</p>"}))
    DescribeCapacityProvidersRequest.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'nextToken', traits: {"smithy.api#documentation" => "<p>The <code>nextToken</code> value returned from a previous paginated\n\t\t\t\t<code>DescribeCapacityProviders</code> request where <code>maxResults</code> was\n\t\t\tused and the results exceeded the value of that parameter. Pagination continues from the\n\t\t\tend of the previous results that returned the <code>nextToken</code> value.</p>\n         <note>\n            <p>This token should be treated as an opaque identifier that is only used to\n                retrieve the next items in a list and not for other programmatic purposes.</p>\n         </note>"}))
