    DescribeServiceDeploymentsResponse.add_member(:failures, Smithy::Schema::Shapes::ShapeRef.new(shape: Failures, location_name: 'failures', traits: {"smithy.api#documentation" => "<p>Any failures associated with the call.</p>\n         <p>If you decsribe a deployment with a service revision created before October 25, 2024,\n\t\t\tthe call fails. The failure includes the service revision ARN and the reason set to\n\t\t\t\t<code>MISSING</code>.</p>"}))
