    LoadBalancer.add_member(:target_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'targetGroupArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the Elastic Load Balancing target group or groups associated with a service or\n\t\t\ttask set.</p>\n         <p>A target group ARN is only specified when using an Application Load Balancer or Network Load Balancer. </p>\n         <p>For services using the <code>ECS</code> deployment controller, you can specify one or\n\t\t\tmultiple target groups. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/register-multiple-targetgroups.html\">Registering multiple target groups with a service</a> in\n\t\t\tthe <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <p>For services using the <code>CODE_DEPLOY</code> deployment controller, you're required\n\t\t\tto define two target groups for the load balancer. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/deployment-type-bluegreen.html\">Blue/green deployment with CodeDeploy</a> in the\n\t\t\t<i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <important>\n            <p>If your service's task definition uses the <code>awsvpc</code> network mode, you\n\t\t\t\tmust choose <code>ip</code> as the target type, not <code>instance</code>. Do this\n\t\t\t\twhen creating your target groups because tasks that use the <code>awsvpc</code>\n\t\t\t\tnetwork mode are associated with an elastic network interface, not an Amazon EC2\n\t\t\t\tinstance. This network mode is required for the Fargate launch\n\t\t\t\ttype.</p>\n         </important>"}))
    LoadBalancer.add_member(:load_balancer_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'loadBalancerName', traits: {"smithy.api#documentation" => "<p>The name of the load balancer to associate with the Amazon ECS service or task set.</p>\n         <p>If you are using an Application Load Balancer or a Network Load Balancer the load balancer name parameter should be\n\t\t\tomitted.</p>"}))
    LoadBalancer.add_member(:container_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'containerName', traits: {"smithy.api#documentation" => "<p>The name of the container (as it appears in a container definition) to associate with\n\t\t\tthe load balancer.</p>\n         <p>You need to specify the container name when configuring the target group for an Amazon ECS\n\t\t\tload balancer.</p>"}))
    LoadBalancer.add_member(:container_port, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'containerPort', traits: {"smithy.api#documentation" => "<p>The port on the container to associate with the load balancer. This port must\n\t\t\tcorrespond to a <code>containerPort</code> in the task definition the tasks in the\n\t\t\tservice are using. For tasks that use the EC2 launch type, the container\n\t\t\tinstance they're launched on must allow ingress traffic on the <code>hostPort</code> of\n\t\t\tthe port mapping.</p>"}))
    LoadBalancer.add_member(:advanced_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AdvancedConfiguration, location_name: 'advancedConfiguration', traits: {"smithy.api#documentation" => "<p>The advanced settings for the load balancer used in blue/green deployments. Specify the alternate target group, listener rules, and IAM role required for traffic shifting during blue/green deployments.</p>"}))
