    ManagedAgent.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedAgentName, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The name of the managed agent. When the execute command feature is turned on, the\n\t\t\tmanaged agent name is <code>ExecuteCommandAgent</code>.</p>"}))
