    ManagedScaling.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedScalingStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>Determines whether to use managed scaling for the capacity provider.</p>"}))
    ManagedScaling.add_member(:target_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedScalingTargetCapacity, location_name: 'targetCapacity', traits: {"smithy.api#documentation" => "<p>The target capacity utilization as a percentage for the capacity provider. The\n\t\t\tspecified value must be greater than <code>0</code> and less than or equal to\n\t\t\t\t<code>100</code>. For example, if you want the capacity provider to maintain 10%\n\t\t\tspare capacity, then that means the utilization is 90%, so use a\n\t\t\t\t<code>targetCapacity</code> of <code>90</code>. The default value of\n\t\t\t\t<code>100</code> percent results in the Amazon EC2 instances in your Auto Scaling group\n\t\t\tbeing completely used.</p>"}))
    ManagedScaling.add_member(:minimum_scaling_step_size, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedScalingStepSize, location_name: 'minimumScalingStepSize', traits: {"smithy.api#documentation" => "<p>The minimum number of Amazon EC2 instances that Amazon ECS will scale out at one time. The scale\n\t\t\tin process is not affected by this parameter If this parameter is omitted, the default\n\t\t\tvalue of <code>1</code> is used.</p>\n         <p>When additional capacity is required, Amazon ECS will scale up the minimum scaling step\n\t\t\tsize even if the actual demand is less than the minimum scaling step size.</p>\n         <p>If you use a capacity provider with an Auto Scaling group configured with more than\n\t\t\tone Amazon EC2 instance type or Availability Zone, Amazon ECS will scale up by the exact minimum\n\t\t\tscaling step size value and will ignore both the maximum scaling step size as well as\n\t\t\tthe capacity demand.</p>"}))
    ManagedScaling.add_member(:maximum_scaling_step_size, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedScalingStepSize, location_name: 'maximumScalingStepSize', traits: {"smithy.api#documentation" => "<p>The maximum number of Amazon EC2 instances that Amazon ECS will scale out at one time. If this\n\t\t\tparameter is omitted, the default value of <code>10000</code> is used.</p>"}))
    ManagedScaling.add_member(:instance_warmup_period, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedScalingInstanceWarmupPeriod, location_name: 'instanceWarmupPeriod', traits: {"smithy.api#documentation" => "<p>The period of time, in seconds, after a newly launched Amazon EC2 instance can contribute\n\t\t\tto CloudWatch metrics for Auto Scaling group. If this parameter is omitted, the default value\n\t\t\tof <code>300</code> seconds is used.</p>"}))
    ManagedScaling.type = Types::ManagedScaling
