    MountPoint.add_member(:source_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'sourceVolume', traits: {"smithy.api#documentation" => "<p>The name of the volume to mount. Must be a volume name referenced in the\n\t\t\t\t<code>name</code> parameter of task definition <code>volume</code>.</p>"}))
    MountPoint.add_member(:container_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'containerPath', traits: {"smithy.api#documentation" => "<p>The path on the container to mount the host volume at.</p>"}))
    MountPoint.add_member(:read_only, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'readOnly', traits: {"smithy.api#documentation" => "<p>If this value is <code>true</code>, the container has read-only access to the volume.\n\t\t\tIf this value is <code>false</code>, then the container can write to the volume. The\n\t\t\tdefault value is <code>false</code>.</p>"}))
