    PlacementConstraint.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementConstraintType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of constraint. Use <code>distinctInstance</code> to ensure that each task in\n\t\t\ta particular group is running on a different container instance. Use\n\t\t\t\t<code>memberOf</code> to restrict the selection to a group of valid\n\t\t\tcandidates.</p>"}))
    PlacementConstraint.add_member(:expression, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'expression', traits: {"smithy.api#documentation" => "<p>A cluster query language expression to apply to the constraint. The expression can\n\t\t\thave a maximum length of 2000 characters. You can't specify an expression if the\n\t\t\tconstraint type is <code>distinctInstance</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/cluster-query-language.html\">Cluster query language</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
