    PlatformDevice.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'id', traits: {"smithy.api#documentation" => "<p>The ID for the GPUs on the container instance. The available GPU IDs can also be\n\t\t\tobtained on the container instance in the\n\t\t\t\t<code>/var/lib/ecs/gpu/nvidia_gpu_info.json</code> file.</p>", "smithy.api#required" => {}}))
