    ProtectedTask.add_member(:protection_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'protectionEnabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>The protection status of the task. If scale-in protection is on for a task, the value\n\t\t\tis <code>true</code>. Otherwise, it is <code>false</code>.</p>"}))
    ProtectedTask.add_member(:expiration_date, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'expirationDate', traits: {"smithy.api#documentation" => "<p>The epoch time when protection for the task will expire.</p>"}))
    ProtectedTask.type = Types::ProtectedTask
