    RepositoryCredentials.add_member(:credentials_parameter, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'credentialsParameter', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the secret containing the private repository\n\t\t\tcredentials.</p>\n         <note>\n            <p>When you use the Amazon ECS API, CLI, or Amazon Web Services SDK, if the secret exists in the same\n\t\t\t\tRegion as the task that you're launching then you can use either the full ARN or\n\t\t\t\tthe name of the secret. When you use the Amazon Web Services Management Console, you must specify the full ARN\n\t\t\t\tof the secret.</p>\n         </note>", "smithy.api#required" => {}}))
