    Resource.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of the resource. Valid values: <code>INTEGER</code>, <code>DOUBLE</code>,\n\t\t\t\t<code>LONG</code>, or <code>STRINGSET</code>.</p>"}))
