    Resource.add_member(:long_value, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'longValue', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>When the <code>longValue</code> type is set, the value of the resource must be an\n\t\t\textended precision floating-point type.</p>"}))
