    RunTaskRequest.add_member(:capacity_provider_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityProviderStrategy, location_name: 'capacityProviderStrategy', traits: {"smithy.api#documentation" => "<p>The capacity provider strategy to use for the task.</p>\n         <p>If a <code>capacityProviderStrategy</code> is specified, the <code>launchType</code>\n\t\t\tparameter must be omitted. If no <code>capacityProviderStrategy</code> or\n\t\t\t\t<code>launchType</code> is specified, the\n\t\t\t\t<code>defaultCapacityProviderStrategy</code> for the cluster is used.</p>\n         <p>When you use cluster auto scaling, you must specify\n\t\t\t\t<code>capacityProviderStrategy</code> and not <code>launchType</code>. </p>\n         <p>A capacity provider strategy can contain a maximum of 20 capacity providers.</p>"}))
    RunTaskRequest.add_member(:cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'cluster', traits: {"smithy.api#documentation" => "<p>The short name or full Amazon Resource Name (ARN) of the cluster to run your task on.\n\t\t\tIf you do not specify a cluster, the default cluster is assumed.</p>\n         <p>Each account receives a default cluster the first time you use the service, but you\n\t\t\tmay also create other clusters.</p>"}))
    RunTaskRequest.add_member(:count, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'count', traits: {"smithy.api#documentation" => "<p>The number of instantiations of the specified task to place on your cluster. You can\n\t\t\tspecify up to 10 tasks for each call.</p>"}))
    RunTaskRequest.add_member(:enable_ecs_managed_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableECSManagedTags', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether to use Amazon ECS managed tags for the task. For more information, see\n\t\t\t\t<a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-using-tags.html\">Tagging Your Amazon ECS\n\t\t\t\tResources</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    RunTaskRequest.add_member(:enable_execute_command, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableExecuteCommand', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Determines whether to use the execute command functionality for the containers in this\n\t\t\ttask. If <code>true</code>, this enables execute command functionality on all containers\n\t\t\tin the task.</p>\n         <p>If <code>true</code>, then the task definition must have a task role, or you must\n\t\t\tprovide one as an override.</p>"}))
    RunTaskRequest.add_member(:group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'group', traits: {"smithy.api#documentation" => "<p>The name of the task group to associate with the task. The default value is the family\n\t\t\tname of the task definition (for example, <code>family:my-family-name</code>).</p>"}))
    RunTaskRequest.add_member(:launch_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchType, location_name: 'launchType', traits: {"smithy.api#documentation" => "<p>The infrastructure to run your standalone task on. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/launch_types.html\">Amazon ECS\n\t\t\t\tlaunch types</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <p>The <code>FARGATE</code> launch type runs your tasks on Fargate On-Demand\n\t\t\tinfrastructure.</p>\n         <note>\n            <p>Fargate Spot infrastructure is available for use but a capacity provider\n\t\t\t\tstrategy must be used. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/fargate-capacity-providers.html\">Fargate capacity providers</a> in the\n\t\t\t\t\t<i>Amazon ECS Developer Guide</i>.</p>\n         </note>\n         <p>The <code>EC2</code> launch type runs your tasks on Amazon EC2 instances registered to your\n\t\t\tcluster.</p>\n         <p>The <code>EXTERNAL</code> launch type runs your tasks on your on-premises server or\n\t\t\tvirtual machine (VM) capacity registered to your cluster.</p>\n         <p>A task can use either a launch type or a capacity provider strategy. If a\n\t\t\t\t<code>launchType</code> is specified, the <code>capacityProviderStrategy</code>\n\t\t\tparameter must be omitted.</p>\n         <p>When you use cluster auto scaling, you must specify\n\t\t\t\t<code>capacityProviderStrategy</code> and not <code>launchType</code>. </p>"}))
    RunTaskRequest.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>The network configuration for the task. This parameter is required for task\n\t\t\tdefinitions that use the <code>awsvpc</code> network mode to receive their own elastic\n\t\t\tnetwork interface, and it isn't supported for other network modes. For more information,\n\t\t\tsee <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-networking.html\">Task networking</a>\n\t\t\tin the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    RunTaskRequest.add_member(:overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskOverride, location_name: 'overrides', traits: {"smithy.api#documentation" => "<p>A list of container overrides in JSON format that specify the name of a container in\n\t\t\tthe specified task definition and the overrides it should receive. You can override the\n\t\t\tdefault command for a container (that's specified in the task definition or Docker\n\t\t\timage) with a <code>command</code> override. You can also override existing environment\n\t\t\tvariables (that are specified in the task definition or Docker image) on a container or\n\t\t\tadd new environment variables to it with an <code>environment</code> override.</p>\n         <p>A total of 8192 characters are allowed for overrides. This limit includes the JSON\n\t\t\tformatting characters of the override structure.</p>"}))
    RunTaskRequest.add_member(:placement_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementConstraints, location_name: 'placementConstraints', traits: {"smithy.api#documentation" => "<p>An array of placement constraint objects to use for the task. You can specify up to 10\n\t\t\tconstraints for each task (including constraints in the task definition and those\n\t\t\tspecified at runtime).</p>"}))
    RunTaskRequest.add_member(:placement_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementStrategies, location_name: 'placementStrategy', traits: {"smithy.api#documentation" => "<p>The placement strategy objects to use for the task. You can specify a maximum of 5\n\t\t\tstrategy rules for each task.</p>"}))
    RunTaskRequest.add_member(:platform_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'platformVersion', traits: {"smithy.api#documentation" => "<p>The platform version the task uses. A platform version is only specified for tasks\n\t\t\thosted on Fargate. If one isn't specified, the <code>LATEST</code>\n\t\t\tplatform version is used. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/platform_versions.html\">Fargate platform\n\t\t\t\tversions</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    RunTaskRequest.add_member(:propagate_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: PropagateTags, location_name: 'propagateTags', traits: {"smithy.api#documentation" => "<p>Specifies whether to propagate the tags from the task definition to the task. If no\n\t\t\tvalue is specified, the tags aren't propagated. Tags can only be propagated to the task\n\t\t\tduring task creation. To add tags to a task after task creation, use the<a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_TagResource.html\">TagResource</a> API action.</p>\n         <note>\n            <p>An error will be received if you specify the <code>SERVICE</code> option when\n\t\t\t\trunning a task.</p>\n         </note>"}))
    RunTaskRequest.add_member(:reference_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'referenceId', traits: {"smithy.api#documentation" => "<p>This parameter is only used by Amazon ECS. It is not intended for use by customers.</p>"}))
    RunTaskRequest.add_member(:started_by, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'startedBy', traits: {"smithy.api#documentation" => "<p>An optional tag specified when a task is started. For example, if you automatically\n\t\t\ttrigger a task to run a batch process job, you could apply a unique identifier for that\n\t\t\tjob to your task with the <code>startedBy</code> parameter. You can then identify which\n\t\t\ttasks belong to that job by filtering the results of a <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_ListTasks.html\">ListTasks</a> call with\n\t\t\tthe <code>startedBy</code> value. Up to 128 letters (uppercase and lowercase), numbers,\n\t\t\thyphens (-), forward slash (/), and underscores (_) are allowed.</p>\n         <p>If a task is started by an Amazon ECS service, then the <code>startedBy</code> parameter\n\t\t\tcontains the deployment ID of the service that starts it.</p>"}))
    RunTaskRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The metadata that you apply to the task to help you categorize and organize them. Each\n\t\t\ttag consists of a key and an optional value, both of which you define.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only\n                    one value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources,\n                    remember that other services may have restrictions on allowed characters.\n                    Generally allowed characters are: letters, numbers, and spaces representable in\n                    UTF-8, and the following characters: + - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case-sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase\n                    combination of such as a prefix for either keys or values as it is reserved for\n                    Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with\n                    this prefix do not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    RunTaskRequest.add_member(:task_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskDefinition', traits: {"smithy.api#documentation" => "<p>The <code>family</code> and <code>revision</code> (<code>family:revision</code>) or\n\t\t\tfull ARN of the task definition to run. If a <code>revision</code> isn't specified,\n\t\t\tthe latest <code>ACTIVE</code> revision is used.</p>\n         <p>The full ARN value must match the value that you specified as the\n\t\t\t\t<code>Resource</code> of the principal's permissions policy.</p>\n         <p>When you specify a task definition, you must either specify a specific revision, or\n\t\t\tall revisions in the ARN.</p>\n         <p>To specify a specific revision, include the revision number in the ARN. For example,\n\t\t\tto specify revision 2, use\n\t\t\t\t<code>arn:aws:ecs:us-east-1:111122223333:task-definition/TaskFamilyName:2</code>.</p>\n         <p>To specify all revisions, use the wildcard (*) in the ARN. For example, to specify\n\t\t\tall revisions, use\n\t\t\t\t<code>arn:aws:ecs:us-east-1:111122223333:task-definition/TaskFamilyName:*</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/security_iam_service-with-iam.html#security_iam_service-with-iam-id-based-policies-resources\">Policy Resources for Amazon ECS</a> in the Amazon Elastic Container Service Developer Guide.</p>", "smithy.api#required" => {}}))
    RunTaskRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientToken', traits: {"smithy.api#documentation" => "<p>An identifier that you provide to ensure the idempotency of the request. It must be\n\t\t\tunique and is case sensitive. Up to 64 characters are allowed. The valid characters are\n\t\t\tcharacters in the range of 33-126, inclusive. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/ECS_Idempotency.html\">Ensuring idempotency</a>.</p>", "smithy.api#idempotencyToken" => {}}))
    RunTaskRequest.add_member(:volume_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskVolumeConfigurations, location_name: 'volumeConfigurations', traits: {"smithy.api#documentation" => "<p>The details of the volume that was <code>configuredAtLaunch</code>. You can configure\n\t\t\tthe size, volumeType, IOPS, throughput, snapshot and encryption in in <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_TaskManagedEBSVolumeConfiguration.html\">TaskManagedEBSVolumeConfiguration</a>. The <code>name</code> of the volume must\n\t\t\tmatch the <code>name</code> from the task definition.</p>"}))
    RunTaskRequest.type = Types::RunTaskRequest
    RunTaskResponse.add_member(:tasks, Smithy::Schema::Shapes::ShapeRef.new(shape: Tasks, location_name: 'tasks', traits: {"smithy.api#documentation" => "<p>A full description of the tasks that were run. The tasks that were successfully placed\n\t\t\ton your cluster are described here.</p>"}))
    RunTaskResponse.add_member(:failures, Smithy::Schema::Shapes::ShapeRef.new(shape: Failures, location_name: 'failures', traits: {"smithy.api#documentation" => "<p>Any failures associated with the call.</p>\n         <p>For information about how to address failures, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-event-messages.html#service-event-messages-list\">Service event messages</a> and <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/api_failures_messages.html\">API failure\n\t\t\t\treasons</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
