    Service.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status of the service. The valid values are <code>ACTIVE</code>,\n\t\t\t\t<code>DRAINING</code>, or <code>INACTIVE</code>.</p>"}))
    Service.add_member(:desired_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'desiredCount', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The desired number of instantiations of the task definition to keep running on the\n\t\t\tservice. This value is specified when the service is created with <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_CreateService.html\">CreateService</a> , and it can be modified with <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_UpdateService.html\">UpdateService</a>.</p>"}))
