    Service.add_member(:platform_family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'platformFamily', traits: {"smithy.api#documentation" => "<p>The operating system that your tasks in the service run on. A platform family is\n\t\t\tspecified only for tasks using the Fargate launch type. </p>\n         <p> All tasks that run as part of this service must use the same\n\t\t\t\t<code>platformFamily</code> value as the service (for example,\n\t\t\t<code>LINUX</code>).</p>"}))
    Service.add_member(:task_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskDefinition', traits: {"smithy.api#documentation" => "<p>The task definition to use for tasks in the service. This value is specified when the\n\t\t\tservice is created with <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_CreateService.html\">CreateService</a>,\n\t\t\tand it can be modified with <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_UpdateService.html\">UpdateService</a>.</p>"}))
    Service.add_member(:deployment_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentConfiguration, location_name: 'deploymentConfiguration', traits: {"smithy.api#documentation" => "<p>Optional deployment parameters that control how many tasks run during the deployment\n\t\t\tand the ordering of stopping and starting tasks.</p>"}))
    Service.add_member(:task_sets, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskSets, location_name: 'taskSets', traits: {"smithy.api#documentation" => "<p>Information about a set of Amazon ECS tasks in either an CodeDeploy or an <code>EXTERNAL</code>\n\t\t\tdeployment. An Amazon ECS task set includes details such as the desired number of tasks, how\n\t\t\tmany tasks are running, and whether the task set serves production traffic.</p>"}))
    Service.add_member(:deployments, Smithy::Schema::Shapes::ShapeRef.new(shape: Deployments, location_name: 'deployments', traits: {"smithy.api#documentation" => "<p>The current state of deployments for the service.</p>"}))
    Service.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'roleArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that's associated with the service. It allows the Amazon ECS\n\t\t\tcontainer agent to register container instances with an Elastic Load Balancing load balancer.</p>"}))
    Service.add_member(:events, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceEvents, location_name: 'events', traits: {"smithy.api#documentation" => "<p>The event stream for your service. A maximum of 100 of the latest events are\n\t\t\tdisplayed.</p>"}))
    Service.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'createdAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the service was created.</p>"}))
    Service.add_member(:placement_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementConstraints, location_name: 'placementConstraints', traits: {"smithy.api#documentation" => "<p>The placement constraints for the tasks in the service.</p>"}))
