    Service.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'networkConfiguration', traits: {"smithy.api#documentation" => "<p>The VPC subnet and security group configuration for tasks that receive their own\n            elastic network interface by using the <code>awsvpc</code> networking mode.</p>"}))
    Service.add_member(:health_check_grace_period_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'healthCheckGracePeriodSeconds', traits: {"smithy.api#documentation" => "<p>The period of time, in seconds, that the Amazon ECS service scheduler ignores unhealthy\n\t\t\tElastic Load Balancing target health checks after a task has first started.</p>"}))
    Service.add_member(:scheduling_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: SchedulingStrategy, location_name: 'schedulingStrategy', traits: {"smithy.api#documentation" => "<p>The scheduling strategy to use for the service. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs_services.html\">Services</a>.</p>\n         <p>There are two service scheduler strategies available.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>REPLICA</code>-The replica scheduling strategy places and\n\t\t\t\t\tmaintains the desired number of tasks across your cluster. By default, the\n\t\t\t\t\tservice scheduler spreads tasks across Availability Zones. You can use task\n\t\t\t\t\tplacement strategies and constraints to customize task placement\n\t\t\t\t\tdecisions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DAEMON</code>-The daemon scheduling strategy deploys exactly one\n\t\t\t\t\ttask on each active container instance. This task meets all of the task\n\t\t\t\t\tplacement constraints that you specify in your cluster. The service scheduler\n\t\t\t\t\talso evaluates the task placement constraints for running tasks. It stop tasks\n\t\t\t\t\tthat don't meet the placement constraints.</p>\n               <note>\n                  <p>Fargate tasks don't support the <code>DAEMON</code>\n\t\t\t\t\t\tscheduling strategy.</p>\n               </note>\n            </li>\n         </ul>"}))
    Service.add_member(:deployment_controller, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentController, location_name: 'deploymentController', traits: {"smithy.api#documentation" => "<p>The deployment controller type the service is using. </p>"}))
    Service.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The metadata that you apply to the service to help you categorize and organize them.\n\t\t\tEach tag consists of a key and an optional value. You define bot the key and\n\t\t\tvalue.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only\n                    one value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources,\n                    remember that other services may have restrictions on allowed characters.\n                    Generally allowed characters are: letters, numbers, and spaces representable in\n                    UTF-8, and the following characters: + - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case-sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase\n                    combination of such as a prefix for either keys or values as it is reserved for\n                    Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with\n                    this prefix do not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    Service.add_member(:created_by, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'createdBy', traits: {"smithy.api#documentation" => "<p>The principal that created the service.</p>"}))
    Service.add_member(:enable_ecs_managed_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableECSManagedTags', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Determines whether to use Amazon ECS managed tags for the tasks in the service. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-using-tags.html\">Tagging Your Amazon ECS\n\t\t\t\tResources</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    Service.add_member(:propagate_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: PropagateTags, location_name: 'propagateTags', traits: {"smithy.api#documentation" => "<p>Determines whether to propagate the tags from the task definition or the service to\n\t\t\tthe task. If no value is specified, the tags aren't propagated.</p>"}))
    Service.add_member(:enable_execute_command, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableExecuteCommand', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Determines whether the execute command functionality is turned on for the service. If\n\t\t\t\t<code>true</code>, the execute command functionality is turned on for all containers\n\t\t\tin tasks as part of the service.</p>"}))
    Service.add_member(:availability_zone_rebalancing, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneRebalancing, location_name: 'availabilityZoneRebalancing', traits: {"smithy.api#documentation" => "<p>Indicates whether to use Availability Zone rebalancing for the service.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-rebalancing.html\">Balancing an Amazon ECS service across Availability Zones</a> in\n\t\t\tthe <i>\n               <i>Amazon Elastic Container Service Developer Guide</i>\n            </i>.</p>"}))
    Service.type = Types::Service
    ServiceConnectClientAlias.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: PortNumber, location_name: 'port', traits: {"smithy.api#documentation" => "<p>The listening port number for the Service Connect proxy. This port is available\n\t\t\tinside of all of the tasks within the same namespace.</p>\n         <p>To avoid changing your applications in client Amazon ECS services, set this to the same\n\t\t\tport that the client application uses by default. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-connect.html\">Service Connect</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>", "smithy.api#required" => {}}))
    ServiceConnectClientAlias.add_member(:dns_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'dnsName', traits: {"smithy.api#documentation" => "<p>The <code>dnsName</code> is the name that you use in the applications of client tasks\n\t\t\tto connect to this service. The name must be a valid DNS name but doesn't need to be\n\t\t\tfully-qualified. The name can include up to 127 characters. The name can include\n\t\t\tlowercase letters, numbers, underscores (_), hyphens (-), and periods (.). The name\n\t\t\tcan't start with a hyphen.</p>\n         <p>If this parameter isn't specified, the default value of <code>discoveryName.namespace</code> is used. If the <code>discoveryName</code> isn't specified, the port mapping name from the task definition is used in <code>portName.namespace</code>.</p>\n         <p>To avoid changing your applications in client Amazon ECS services, set this to the same\n\t\t\tname that the client application uses by default. For example, a few common names are\n\t\t\t\t<code>database</code>, <code>db</code>, or the lowercase name of a database, such as\n\t\t\t\t<code>mysql</code> or <code>redis</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/service-connect.html\">Service Connect</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    ServiceConnectClientAlias.add_member(:test_traffic_rules, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceConnectTestTrafficRules, location_name: 'testTrafficRules', traits: {"smithy.api#documentation" => "<p>The configuration for test traffic routing rules used during blue/green deployments with Amazon ECS Service Connect. This allows you to route a portion of traffic to the new service revision of your service for testing before shifting all production traffic.</p>"}))
    ServiceConnectClientAlias.type = Types::ServiceConnectClientAlias
    ServiceConnectClientAliasList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceConnectClientAlias)
    ServiceConnectConfiguration.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether to use Service Connect with this service.</p>", "smithy.api#required" => {}}))
    ServiceConnectConfiguration.add_member(:namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'namespace', traits: {"smithy.api#documentation" => "<p>The namespace name or full Amazon Resource Name (ARN) of the Cloud Map namespace for use with Service Connect. The namespace must be in\n\t\t\tthe same Amazon Web Services Region as the Amazon ECS service and cluster. The type of namespace doesn't\n\t\t\taffect Service Connect. For more information about Cloud Map, see <a href=\"https://docs.aws.amazon.com/cloud-map/latest/dg/working-with-services.html\">Working\n\t\t\t\twith Services</a> in the <i>Cloud Map Developer Guide</i>.</p>"}))
    ServiceConnectConfiguration.add_member(:services, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceConnectServiceList, location_name: 'services', traits: {"smithy.api#documentation" => "<p>The list of Service Connect service objects. These are names and aliases (also known\n\t\t\tas endpoints) that are used by other Amazon ECS services to connect to this service.\n\t\t\t</p>\n         <p>This field is not required for a \"client\" Amazon ECS service that's a member of a namespace\n\t\t\tonly to connect to other services within the namespace. An example of this would be a\n\t\t\tfrontend application that accepts incoming requests from either a load balancer that's\n\t\t\tattached to the service or by other means.</p>\n         <p>An object selects a port from the task definition, assigns a name for the Cloud Map\n\t\t\tservice, and a list of aliases (endpoints) and ports for client applications to refer to\n\t\t\tthis service.</p>"}))
    ServiceConnectConfiguration.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'logConfiguration'))
    ServiceConnectConfiguration.type = Types::ServiceConnectConfiguration
    ServiceConnectService.add_member(:port_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'portName', traits: {"smithy.api#documentation" => "<p>The <code>portName</code> must match the name of one of the <code>portMappings</code>\n\t\t\tfrom all the containers in the task definition of this Amazon ECS service.</p>", "smithy.api#required" => {}}))
    ServiceConnectService.add_member(:discovery_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'discoveryName', traits: {"smithy.api#documentation" => "<p>The <code>discoveryName</code> is the name of the new Cloud Map service that Amazon ECS creates\n\t\t\tfor this Amazon ECS service. This must be unique within the Cloud Map namespace. The name can contain up to 64 characters. The name can include lowercase letters,\n\t\t\tnumbers, underscores (_), and hyphens (-). The name can't start with a hyphen.</p>\n         <p>If the <code>discoveryName</code> isn't specified, the port mapping name from the task definition is used in <code>portName.namespace</code>.</p>"}))
    ServiceConnectService.add_member(:client_aliases, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceConnectClientAliasList, location_name: 'clientAliases', traits: {"smithy.api#documentation" => "<p>The list of client aliases for this Service Connect service. You use these to assign\n\t\t\tnames that can be used by client applications. The maximum number of client aliases that\n\t\t\tyou can have in this list is 1.</p>\n         <p>Each alias (\"endpoint\") is a fully-qualified name and port number that other Amazon ECS\n\t\t\ttasks (\"clients\") can use to connect to this service.</p>\n         <p>Each name and port mapping must be unique within the namespace.</p>\n         <p>For each <code>ServiceConnectService</code>, you must provide at least one\n\t\t\t\t<code>clientAlias</code> with one <code>port</code>.</p>"}))
    ServiceConnectService.add_member(:ingress_port_override, Smithy::Schema::Shapes::ShapeRef.new(shape: PortNumber, location_name: 'ingressPortOverride', traits: {"smithy.api#documentation" => "<p>The port number for the Service Connect proxy to listen on.</p>\n         <p>Use the value of this field to bypass the proxy for traffic on the port number\n\t\t\tspecified in the named <code>portMapping</code> in the task definition of this\n\t\t\tapplication, and then use it in your VPC security groups to allow traffic into the proxy\n\t\t\tfor this Amazon ECS service.</p>\n         <p>In <code>awsvpc</code> mode and Fargate, the default value is the container port\n\t\t\tnumber. The container port number is in the <code>portMapping</code> in the task\n\t\t\tdefinition. In bridge mode, the default value is the ephemeral port of the\n\t\t\tService Connect proxy.</p>"}))
    ServiceConnectService.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeoutConfiguration, location_name: 'timeout', traits: {"smithy.api#documentation" => "<p>A reference to an object that represents the configured timeouts for\n\t\t\tService Connect.</p>"}))
