    Task.add_member(:cpu, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'cpu', traits: {"smithy.api#documentation" => "<p>The number of CPU units used by the task as expressed in a task definition. It can be\n\t\t\texpressed as an integer using CPU units (for example, <code>1024</code>). It can also be\n\t\t\texpressed as a string using vCPUs (for example, <code>1 vCPU</code> or <code>1\n\t\t\t\tvcpu</code>). String values are converted to an integer that indicates the CPU units\n\t\t\twhen the task definition is registered.</p>\n         <p>If you're using the EC2 launch type or the external launch type, this field is\n\t\t\toptional. Supported values are between <code>128</code> CPU units (<code>0.125</code>\n\t\t\tvCPUs) and <code>196608</code> CPU units (<code>192</code> vCPUs). If you do not specify\n\t\t\ta value, the parameter is ignored.</p>\n         <p>This field is required for Fargate. For information about the valid values, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task_definition_parameters.html#task_size\">Task size</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    Task.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'createdAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task was created. More specifically, it's for\n\t\t\tthe time when the task entered the <code>PENDING</code> state.</p>"}))
    Task.add_member(:desired_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'desiredStatus', traits: {"smithy.api#documentation" => "<p>The desired status of the task. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-lifecycle.html\">Task\n\t\t\tLifecycle</a>.</p>"}))
    Task.add_member(:enable_execute_command, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'enableExecuteCommand', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Determines whether execute command functionality is turned on for this task. If\n\t\t\t\t<code>true</code>, execute command functionality is turned on all the containers in\n\t\t\tthe task.</p>"}))
    Task.add_member(:execution_stopped_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'executionStoppedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task execution stopped.</p>"}))
    Task.add_member(:group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'group', traits: {"smithy.api#documentation" => "<p>The name of the task group that's associated with the task.</p>"}))
    Task.add_member(:health_status, Smithy::Schema::Shapes::ShapeRef.new(shape: HealthStatus, location_name: 'healthStatus', traits: {"smithy.api#documentation" => "<p>The health status for the task. It's determined by the health of the essential\n\t\t\tcontainers in the task. If all essential containers in the task are reporting as\n\t\t\t\t<code>HEALTHY</code>, the task status also reports as <code>HEALTHY</code>. If any\n\t\t\tessential containers in the task are reporting as <code>UNHEALTHY</code> or\n\t\t\t\t<code>UNKNOWN</code>, the task status also reports as <code>UNHEALTHY</code> or\n\t\t\t\t<code>UNKNOWN</code>.</p>\n         <note>\n            <p>The Amazon ECS container agent doesn't monitor or report on Docker health checks that\n\t\t\t\tare embedded in a container image and not specified in the container definition. For\n\t\t\t\texample, this includes those specified in a parent image or from the image's\n\t\t\t\tDockerfile. Health check parameters that are specified in a container definition\n\t\t\t\toverride any Docker health checks that are found in the container image.</p>\n         </note>"}))
    Task.add_member(:inference_accelerators, Smithy::Schema::Shapes::ShapeRef.new(shape: InferenceAccelerators, location_name: 'inferenceAccelerators', traits: {"smithy.api#documentation" => "<p>The Elastic Inference accelerator that's associated with the task.</p>"}))
    Task.add_member(:last_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'lastStatus', traits: {"smithy.api#documentation" => "<p>The last known status for the task. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-lifecycle.html\">Task\n\t\t\t\tLifecycle</a>.</p>"}))
    Task.add_member(:launch_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchType, location_name: 'launchType', traits: {"smithy.api#documentation" => "<p>The infrastructure where your task runs on. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/launch_types.html\">Amazon ECS\n\t\t\t\tlaunch types</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    Task.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'memory', traits: {"smithy.api#documentation" => "<p>The amount of memory (in MiB) that the task uses as expressed in a task definition. It\n\t\t\tcan be expressed as an integer using MiB (for example, <code>1024</code>). If it's\n\t\t\texpressed as a string using GB (for example, <code>1GB</code> or <code>1 GB</code>),\n\t\t\tit's converted to an integer indicating the MiB when the task definition is\n\t\t\tregistered.</p>\n         <p>If you use the EC2 launch type, this field is optional.</p>\n         <p>If you use the Fargate launch type, this field is required. You must use\n\t\t\tone of the following values. The value that you choose determines the range of supported\n\t\t\tvalues for the <code>cpu</code> parameter.</p>\n         <ul>\n            <li>\n               <p>512 (0.5 GB), 1024 (1 GB), 2048 (2 GB) - Available <code>cpu</code> values: 256 (.25 vCPU)</p>\n            </li>\n            <li>\n               <p>1024 (1 GB), 2048 (2 GB), 3072 (3 GB), 4096 (4 GB) - Available <code>cpu</code> values: 512 (.5 vCPU)</p>\n            </li>\n            <li>\n               <p>2048 (2 GB), 3072 (3 GB), 4096 (4 GB), 5120 (5 GB), 6144 (6 GB), 7168 (7 GB), 8192 (8 GB) - Available <code>cpu</code> values: 1024 (1 vCPU)</p>\n            </li>\n            <li>\n               <p>Between 4096 (4 GB) and 16384 (16 GB) in increments of 1024 (1 GB) - Available <code>cpu</code> values: 2048 (2 vCPU)</p>\n            </li>\n            <li>\n               <p>Between 8192 (8 GB) and 30720 (30 GB) in increments of 1024 (1 GB) - Available <code>cpu</code> values: 4096 (4 vCPU)</p>\n            </li>\n            <li>\n               <p>Between 16 GB and 60 GB in 4 GB increments - Available <code>cpu</code> values: 8192 (8 vCPU)</p>\n               <p>This option requires Linux platform <code>1.4.0</code> or\n                                        later.</p>\n            </li>\n            <li>\n               <p>Between 32GB and 120 GB in 8 GB increments - Available <code>cpu</code> values: 16384 (16 vCPU)</p>\n               <p>This option requires Linux platform <code>1.4.0</code> or\n                                        later.</p>\n            </li>\n         </ul>"}))
    Task.add_member(:overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskOverride, location_name: 'overrides', traits: {"smithy.api#documentation" => "<p>One or more container overrides.</p>"}))
    Task.add_member(:platform_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'platformVersion', traits: {"smithy.api#documentation" => "<p>The platform version where your task runs on. A platform version is only specified for\n\t\t\ttasks that use the Fargate launch type. If you didn't specify one, the\n\t\t\t\t<code>LATEST</code> platform version is used. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/platform_versions.html\">Fargate Platform Versions</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    Task.add_member(:platform_family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'platformFamily', traits: {"smithy.api#documentation" => "<p>The operating system that your tasks are running on. A platform family is specified\n\t\t\tonly for tasks that use the Fargate launch type. </p>\n         <p> All tasks that run as part of this service must use the same\n\t\t\t\t<code>platformFamily</code> value as the service (for example,\n\t\t\t<code>LINUX.</code>).</p>"}))
    Task.add_member(:pull_started_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'pullStartedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the container image pull began.</p>"}))
    Task.add_member(:pull_stopped_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'pullStoppedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the container image pull completed.</p>"}))
    Task.add_member(:started_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'startedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task started. More specifically, it's for the\n\t\t\ttime when the task transitioned from the <code>PENDING</code> state to the\n\t\t\t\t<code>RUNNING</code> state.</p>"}))
    Task.add_member(:started_by, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'startedBy', traits: {"smithy.api#documentation" => "<p>The tag specified when a task is started. If an Amazon ECS service started the task, the\n\t\t\t\t<code>startedBy</code> parameter contains the deployment ID of that service.</p>"}))
    Task.add_member(:stop_code, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskStopCode, location_name: 'stopCode', traits: {"smithy.api#documentation" => "<p>The stop code indicating why a task was stopped. The <code>stoppedReason</code> might\n\t\t\tcontain additional details. </p>\n         <p>For more information about stop code, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/stopped-task-error-codes.html\">Stopped tasks\n\t\t\t\terror codes</a> in the <i>Amazon ECS Developer Guide</i>.</p>"}))
    Task.add_member(:stopped_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'stoppedAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task was stopped. More specifically, it's for\n\t\t\tthe time when the task transitioned from the <code>RUNNING</code> state to the\n\t\t\t\t<code>STOPPED</code> state.</p>"}))
    Task.add_member(:stopped_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'stoppedReason', traits: {"smithy.api#documentation" => "<p>The reason that the task was stopped.</p>"}))
    Task.add_member(:stopping_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'stoppingAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task stops. More specifically, it's for the\n\t\t\ttime when the task transitions from the <code>RUNNING</code> state to\n\t\t\t\t<code>STOPPING</code>.</p>"}))
    Task.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The metadata that you apply to the task to help you categorize and organize the task.\n\t\t\tEach tag consists of a key and an optional value. You define both the key and\n\t\t\tvalue.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only\n                    one value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources,\n                    remember that other services may have restrictions on allowed characters.\n                    Generally allowed characters are: letters, numbers, and spaces representable in\n                    UTF-8, and the following characters: + - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case-sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase\n                    combination of such as a prefix for either keys or values as it is reserved for\n                    Amazon Web Services use. You cannot edit or delete tag keys or values with this prefix. Tags with\n                    this prefix do not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    Task.add_member(:task_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the task.</p>"}))
    Task.add_member(:task_definition_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskDefinitionArn', traits: {"smithy.api#documentation" => "<p>The ARN of the task definition that creates the task.</p>"}))
    Task.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'version', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The version counter for the task. Every time a task experiences a change that starts a\n\t\t\tCloudWatch event, the version counter is incremented. If you replicate your Amazon ECS task state\n\t\t\twith CloudWatch Events, you can compare the version of a task reported by the Amazon ECS API\n\t\t\tactions with the version reported in CloudWatch Events for the task (inside the\n\t\t\t\t<code>detail</code> object) to verify that the version in your event stream is\n\t\t\tcurrent.</p>"}))
    Task.add_member(:ephemeral_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: EphemeralStorage, location_name: 'ephemeralStorage', traits: {"smithy.api#documentation" => "<p>The ephemeral storage settings for the task.</p>"}))
    Task.add_member(:fargate_ephemeral_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskEphemeralStorage, location_name: 'fargateEphemeralStorage', traits: {"smithy.api#documentation" => "<p>The Fargate ephemeral storage settings for the task.</p>"}))
    Task.type = Types::Task
    TaskDefinition.add_member(:task_definition_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskDefinitionArn', traits: {"smithy.api#documentation" => "<p>The full Amazon Resource Name (ARN) of the task definition.</p>"}))
    TaskDefinition.add_member(:container_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerDefinitions, location_name: 'containerDefinitions', traits: {"smithy.api#documentation" => "<p>A list of container definitions in JSON format that describe the different containers\n\t\t\tthat make up your task. For more information about container definition parameters and\n\t\t\tdefaults, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task_defintions.html\">Amazon ECS Task\n\t\t\t\tDefinitions</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'family', traits: {"smithy.api#documentation" => "<p>The name of a family that this task definition is registered to. Up to 255 characters\n\t\t\tare allowed. Letters (both uppercase and lowercase letters), numbers, hyphens (-), and\n\t\t\tunderscores (_) are allowed.</p>\n         <p>A family groups multiple versions of a task definition. Amazon ECS gives the first task\n\t\t\tdefinition that you registered to a family a revision number of 1. Amazon ECS gives\n\t\t\tsequential revision numbers to each task definition that you add.</p>"}))
    TaskDefinition.add_member(:task_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskRoleArn', traits: {"smithy.api#documentation" => "<p>The short name or full Amazon Resource Name (ARN) of the Identity and Access Management role that grants containers in the\n\t\t\ttask permission to call Amazon Web Services APIs on your behalf. For informationabout the required\n\t\t\tIAM roles for Amazon ECS, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/security-ecs-iam-role-overview.html\">IAM\n\t\t\t\troles for Amazon ECS</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'executionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the task execution role that grants the Amazon ECS container agent\n            permission to make Amazon Web Services API calls on your behalf. For informationabout the required IAM roles for Amazon ECS, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/security-ecs-iam-role-overview.html\">IAM roles for Amazon ECS</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:network_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkMode, location_name: 'networkMode', traits: {"smithy.api#documentation" => "<p>The Docker networking mode to use for the containers in the task. The valid values are\n                <code>none</code>, <code>bridge</code>, <code>awsvpc</code>, and <code>host</code>.\n            If no network mode is specified, the default is <code>bridge</code>.</p>\n         <p>For Amazon ECS tasks on Fargate, the <code>awsvpc</code> network mode is required. \n            For Amazon ECS tasks on Amazon EC2 Linux instances, any network mode can be used.  For Amazon ECS tasks on Amazon EC2 Windows instances, <code><default></code> or <code>awsvpc</code> can be used. If the network\n            mode is set to <code>none</code>, you cannot specify port mappings in your container\n            definitions, and the tasks containers do not have external connectivity. The\n                <code>host</code> and <code>awsvpc</code> network modes offer the highest networking\n            performance for containers because they use the EC2 network stack instead of the\n            virtualized network stack provided by the <code>bridge</code> mode.</p>\n         <p>With the <code>host</code> and <code>awsvpc</code> network modes, exposed container\n            ports are mapped directly to the corresponding host port (for the <code>host</code>\n            network mode) or the attached elastic network interface port (for the\n                <code>awsvpc</code> network mode), so you cannot take advantage of dynamic host port\n            mappings. </p>\n         <important>\n            <p>When using the <code>host</code> network mode, you should not run\n                            containers using the root user (UID 0). It is considered best practice\n                            to use a non-root user.</p>\n         </important>\n         <p>If the network mode is <code>awsvpc</code>, the task is allocated an elastic network\n            interface, and you must specify a <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_NetworkConfiguration.html\">NetworkConfiguration</a> value when you create\n            a service or run a task with the task definition. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-networking.html\">Task Networking</a> in the\n                <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <p>If the network mode is <code>host</code>, you cannot run multiple instantiations of the\n            same task on a single container instance when port mappings are used.</p>"}))
    TaskDefinition.add_member(:revision, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'revision', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The revision of the task in a particular family. The revision is a version number of a\n\t\t\ttask definition in a family. When you register a task definition for the first time, the\n\t\t\trevision is <code>1</code>. Each time that you register a new revision of a task\n\t\t\tdefinition in the same family, the revision value always increases by one. This is even\n\t\t\tif you deregistered previous revisions in this family.</p>"}))
    TaskDefinition.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeList, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>The list of data volume definitions for the task. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/using_data_volumes.html\">Using data volumes in tasks</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <note>\n            <p>The <code>host</code> and <code>sourcePath</code> parameters aren't supported for\n\t\t\t\ttasks run on Fargate. </p>\n         </note>"}))
    TaskDefinition.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDefinitionStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status of the task definition.</p>"}))
    TaskDefinition.add_member(:requires_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: RequiresAttributes, location_name: 'requiresAttributes', traits: {"smithy.api#documentation" => "<p>The container instance attributes required by your task. When an Amazon EC2 instance is\n\t\t\tregistered to your cluster, the Amazon ECS container agent assigns some standard attributes\n\t\t\tto the instance. You can apply custom attributes. These are specified as key-value pairs\n\t\t\tusing the Amazon ECS console or the <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_PutAttributes.html\">PutAttributes</a>\n\t\t\tAPI. These attributes are used when determining task placement for tasks hosted on Amazon EC2\n\t\t\tinstances. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-placement-constraints.html#attributes\">Attributes</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <note>\n            <p>This parameter isn't supported for tasks run on Fargate.</p>\n         </note>"}))
    TaskDefinition.add_member(:placement_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDefinitionPlacementConstraints, location_name: 'placementConstraints', traits: {"smithy.api#documentation" => "<p>An array of placement constraint objects to use for tasks.</p>\n         <note>\n            <p>This parameter isn't supported for tasks run on Fargate.</p>\n         </note>"}))
    TaskDefinition.add_member(:compatibilities, Smithy::Schema::Shapes::ShapeRef.new(shape: CompatibilityList, location_name: 'compatibilities', traits: {"smithy.api#documentation" => "<p>Amazon ECS validates the task definition parameters with those supported by the launch\n\t\t\ttype. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/launch_types.html\">Amazon ECS launch types</a>\n\t\t\tin the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:runtime_platform, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimePlatform, location_name: 'runtimePlatform', traits: {"smithy.api#documentation" => "<p>The operating system that your task definitions are running on. A platform family is\n\t\t\tspecified only for tasks using the Fargate launch type. </p>\n         <p>When you specify a task in a service, this value must match the\n\t\t\t\t<code>runtimePlatform</code> value of the service.</p>"}))
    TaskDefinition.add_member(:requires_compatibilities, Smithy::Schema::Shapes::ShapeRef.new(shape: CompatibilityList, location_name: 'requiresCompatibilities', traits: {"smithy.api#documentation" => "<p>The task launch types the task definition was validated against. The valid values are\n\t\t\t\t<code>EC2</code>, <code>FARGATE</code>, and <code>EXTERNAL</code>. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/launch_types.html\">Amazon ECS launch types</a>\n\t\t\tin the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:cpu, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'cpu', traits: {"smithy.api#documentation" => "<p>The number of <code>cpu</code> units used by the task. If you use the EC2 launch type,\n\t\t\tthis field is optional. Any value can be used. If you use the Fargate launch type, this\n\t\t\tfield is required. You must use one of the following values. The value that you choose\n\t\t\tdetermines your range of valid values for the <code>memory</code> parameter.</p>\n         <p>If you're using the EC2 launch type or the external launch type, this\n\t\t\tfield is optional. Supported values are between <code>128</code> CPU units\n\t\t\t\t(<code>0.125</code> vCPUs) and <code>196608</code> CPU units (<code>192</code>\n\t\t\tvCPUs). </p>\n         <p>This field is required for Fargate. For information about the valid values, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task_definition_parameters.html#task_size\">Task size</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:memory, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'memory', traits: {"smithy.api#documentation" => "<p>The amount (in MiB) of memory used by the task.</p>\n         <p>If your tasks runs on Amazon EC2 instances, you must specify either a task-level memory\n\t\t\tvalue or a container-level memory value. This field is optional and any value can be\n\t\t\tused. If a task-level memory value is specified, the container-level memory value is\n\t\t\toptional. For more information regarding container-level memory and memory reservation,\n\t\t\tsee <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_ContainerDefinition.html\">ContainerDefinition</a>.</p>\n         <p>If your tasks runs on Fargate, this field is required. You must use one of the\n\t\t\tfollowing values. The value you choose determines your range of valid values for the\n\t\t\t\t<code>cpu</code> parameter.</p>\n         <ul>\n            <li>\n               <p>512 (0.5 GB), 1024 (1 GB), 2048 (2 GB) - Available <code>cpu</code> values: 256 (.25 vCPU)</p>\n            </li>\n            <li>\n               <p>1024 (1 GB), 2048 (2 GB), 3072 (3 GB), 4096 (4 GB) - Available <code>cpu</code> values: 512 (.5 vCPU)</p>\n            </li>\n            <li>\n               <p>2048 (2 GB), 3072 (3 GB), 4096 (4 GB), 5120 (5 GB), 6144 (6 GB), 7168 (7 GB), 8192 (8 GB) - Available <code>cpu</code> values: 1024 (1 vCPU)</p>\n            </li>\n            <li>\n               <p>Between 4096 (4 GB) and 16384 (16 GB) in increments of 1024 (1 GB) - Available <code>cpu</code> values: 2048 (2 vCPU)</p>\n            </li>\n            <li>\n               <p>Between 8192 (8 GB) and 30720 (30 GB) in increments of 1024 (1 GB) - Available <code>cpu</code> values: 4096 (4 vCPU)</p>\n            </li>\n            <li>\n               <p>Between 16 GB and 60 GB in 4 GB increments - Available <code>cpu</code> values: 8192 (8 vCPU)</p>\n               <p>This option requires Linux platform <code>1.4.0</code> or\n                                        later.</p>\n            </li>\n            <li>\n               <p>Between 32GB and 120 GB in 8 GB increments - Available <code>cpu</code> values: 16384 (16 vCPU)</p>\n               <p>This option requires Linux platform <code>1.4.0</code> or\n                                        later.</p>\n            </li>\n         </ul>"}))
    TaskDefinition.add_member(:inference_accelerators, Smithy::Schema::Shapes::ShapeRef.new(shape: InferenceAccelerators, location_name: 'inferenceAccelerators', traits: {"smithy.api#documentation" => "<p>The Elastic Inference accelerator that's associated with the task.</p>"}))
    TaskDefinition.add_member(:pid_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: PidMode, location_name: 'pidMode', traits: {"smithy.api#documentation" => "<p>The process namespace to use for the containers in the task. The valid\n                            values are <code>host</code> or <code>task</code>. On Fargate for\n                            Linux containers, the only valid value is <code>task</code>. For\n                            example, monitoring sidecars might need <code>pidMode</code> to access\n                            information about other containers running in the same task.</p>\n         <p>If <code>host</code> is specified, all containers within the tasks\n                            that specified the <code>host</code> PID mode on the same container\n                            instance share the same process namespace with the host Amazon EC2\n                            instance.</p>\n         <p>If <code>task</code> is specified, all containers within the specified\n                            task share the same process namespace.</p>\n         <p>If no value is specified, the\n                            default is a private namespace for each container.</p>\n         <p>If the <code>host</code> PID mode is used, there's a heightened risk\n                            of undesired process namespace exposure.</p>\n         <note>\n            <p>This parameter is not supported for Windows containers.</p>\n         </note>\n         <note>\n            <p>This parameter is only supported for tasks that are hosted on\n        Fargate if the tasks are using platform version <code>1.4.0</code> or later\n        (Linux). This isn't supported for Windows containers on\n        Fargate.</p>\n         </note>"}))
    TaskDefinition.add_member(:ipc_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: IpcMode, location_name: 'ipcMode', traits: {"smithy.api#documentation" => "<p>The IPC resource namespace to use for the containers in the task. The valid values are\n                <code>host</code>, <code>task</code>, or <code>none</code>. If <code>host</code> is\n            specified, then all containers within the tasks that specified the <code>host</code> IPC\n            mode on the same container instance share the same IPC resources with the host Amazon EC2\n            instance. If <code>task</code> is specified, all containers within the specified task\n            share the same IPC resources. If <code>none</code> is specified, then IPC resources\n            within the containers of a task are private and not shared with other containers in a\n            task or on the container instance. If no value is specified, then the IPC resource\n            namespace sharing depends on the Docker daemon setting on the container instance.</p>\n         <p>If the <code>host</code> IPC mode is used, be aware that there is a heightened risk of\n            undesired IPC namespace expose.</p>\n         <p>If you are setting namespaced kernel parameters using <code>systemControls</code> for\n            the containers in the task, the following will apply to your IPC resource namespace. For\n            more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task_definition_parameters.html\">System\n                Controls</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>\n         <ul>\n            <li>\n               <p>For tasks that use the <code>host</code> IPC mode, IPC namespace related\n                        <code>systemControls</code> are not supported.</p>\n            </li>\n            <li>\n               <p>For tasks that use the <code>task</code> IPC mode, IPC namespace related\n                        <code>systemControls</code> will apply to all containers within a\n                    task.</p>\n            </li>\n         </ul>\n         <note>\n            <p>This parameter is not supported for Windows containers or tasks run on Fargate.</p>\n         </note>"}))
    TaskDefinition.add_member(:proxy_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ProxyConfiguration, location_name: 'proxyConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration details for the App Mesh proxy.</p>\n         <p>Your Amazon ECS container instances require at least version 1.26.0 of the container agent\n\t\t\tand at least version 1.26.0-1 of the <code>ecs-init</code> package to use a proxy\n\t\t\tconfiguration. If your container instances are launched from the Amazon ECS optimized AMI\n\t\t\tversion <code>20190301</code> or later, they contain the required versions of the\n\t\t\tcontainer agent and <code>ecs-init</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-optimized_AMI.html\">Amazon ECS-optimized Linux AMI</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinition.add_member(:registered_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'registeredAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task definition was registered.</p>"}))
    TaskDefinition.add_member(:deregistered_at, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'deregisteredAt', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the time when the task definition was deregistered.</p>"}))
    TaskDefinition.add_member(:registered_by, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'registeredBy', traits: {"smithy.api#documentation" => "<p>The principal that registered the task definition.</p>"}))
    TaskDefinition.add_member(:ephemeral_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: EphemeralStorage, location_name: 'ephemeralStorage', traits: {"smithy.api#documentation" => "<p>The ephemeral storage settings to use for tasks run with the task definition.</p>"}))
    TaskDefinition.add_member(:enable_fault_injection, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'enableFaultInjection', traits: {"smithy.api#documentation" => "<p>Enables fault injection and allows for fault injection requests to be accepted from\n\t\t\tthe task's containers. The default value is <code>false</code>.</p>"}))
    TaskDefinition.type = Types::TaskDefinition
    TaskDefinitionFamilyStatus.add_member(:active, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ACTIVE', traits: {"smithy.api#enumValue" => "ACTIVE"}))
    TaskDefinitionFamilyStatus.add_member(:inactive, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INACTIVE', traits: {"smithy.api#enumValue" => "INACTIVE"}))
    TaskDefinitionFamilyStatus.add_member(:all, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ALL', traits: {"smithy.api#enumValue" => "ALL"}))
    TaskDefinitionField.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TAGS', traits: {"smithy.api#enumValue" => "TAGS"}))
    TaskDefinitionFieldList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDefinitionField)
    TaskDefinitionList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDefinition)
    TaskDefinitionPlacementConstraint.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDefinitionPlacementConstraintType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of constraint. The <code>MemberOf</code> constraint restricts selection to be\n\t\t\tfrom a group of valid candidates.</p>"}))
    TaskDefinitionPlacementConstraint.add_member(:expression, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'expression', traits: {"smithy.api#documentation" => "<p>A cluster query language expression to apply to the constraint. For more information,\n\t\t\tsee <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/cluster-query-language.html\">Cluster query language</a> in the <i>Amazon Elastic Container Service Developer Guide</i>.</p>"}))
    TaskDefinitionPlacementConstraint.type = Types::TaskDefinitionPlacementConstraint
    TaskDefinitionPlacementConstraintType.add_member(:member_of, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MEMBER_OF', traits: {"smithy.api#enumValue" => "memberOf"}))
    TaskDefinitionPlacementConstraints.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDefinitionPlacementConstraint)
    TaskDefinitionStatus.add_member(:active, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ACTIVE', traits: {"smithy.api#enumValue" => "ACTIVE"}))
    TaskDefinitionStatus.add_member(:inactive, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INACTIVE', traits: {"smithy.api#enumValue" => "INACTIVE"}))
    TaskDefinitionStatus.add_member(:delete_in_progress, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DELETE_IN_PROGRESS', traits: {"smithy.api#enumValue" => "DELETE_IN_PROGRESS"}))
    TaskEphemeralStorage.add_member(:size_in_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'sizeInGiB', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The total amount, in GiB, of the ephemeral storage to set for the task. The minimum\n\t\t\tsupported value is <code>20</code> GiB and the maximum supported value is\u2028\n\t\t\t\t<code>200</code> GiB.</p>"}))
    TaskEphemeralStorage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'kmsKeyId', traits: {"smithy.api#documentation" => "<p>Specify an Key Management Service key ID to encrypt the ephemeral storage for the\n\t\t\ttask.</p>"}))
    TaskEphemeralStorage.type = Types::TaskEphemeralStorage
    TaskField.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TAGS', traits: {"smithy.api#enumValue" => "TAGS"}))
    TaskFieldList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TaskField)
    TaskFilesystemType.add_member(:ext3, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EXT3', traits: {"smithy.api#enumValue" => "ext3"}))
    TaskFilesystemType.add_member(:ext4, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'EXT4', traits: {"smithy.api#enumValue" => "ext4"}))
    TaskFilesystemType.add_member(:xfs, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'XFS', traits: {"smithy.api#enumValue" => "xfs"}))
    TaskFilesystemType.add_member(:ntfs, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NTFS', traits: {"smithy.api#enumValue" => "ntfs"}))
    TaskManagedEBSVolumeConfiguration.add_member(:encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'encrypted', traits: {"smithy.api#documentation" => "<p>Indicates whether the volume should be encrypted. If you turn on Region-level Amazon EBS\n\t\t\tencryption by default but set this value as <code>false</code>, the setting is\n\t\t\toverridden and the volume is encrypted with the KMS key specified for Amazon EBS encryption\n\t\t\tby default. This parameter maps 1:1 with the <code>Encrypted</code> parameter of the\n\t\t\t\t<a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in the <i>Amazon EC2 API Reference</i>.</p>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: EBSKMSKeyId, location_name: 'kmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) identifier of the Amazon Web Services Key Management Service key to use for Amazon EBS encryption. When a key\n\t\t\tis specified using this parameter, it overrides Amazon EBS default encryption or any KMS key\n\t\t\tthat you specified for cluster-level managed storage encryption. This parameter maps 1:1\n\t\t\twith the <code>KmsKeyId</code> parameter of the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in\n\t\t\tthe <i>Amazon EC2 API Reference</i>. For more information about encrypting\n\t\t\tAmazon EBS volumes attached to a task, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ebs-kms-encryption.html\">Encrypt data stored in Amazon EBS volumes attached to Amazon ECS tasks</a>.</p>\n         <important>\n            <p>Amazon Web Services authenticates the Amazon Web Services Key Management Service key asynchronously. Therefore, if you specify an\n\t\t\t\tID, alias, or ARN that is invalid, the action can appear to complete, but\n\t\t\t\teventually fails.</p>\n         </important>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:volume_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EBSVolumeType, location_name: 'volumeType', traits: {"smithy.api#documentation" => "<p>The volume type. This parameter maps 1:1 with the <code>VolumeType</code> parameter of\n\t\t\tthe <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in the <i>Amazon EC2 API Reference</i>. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ebs-volume-types.html\">Amazon EBS volume types</a> in\n\t\t\tthe <i>Amazon EC2 User Guide</i>.</p>\n         <p>The following are the supported volume types.</p>\n         <ul>\n            <li>\n               <p>General Purpose SSD: <code>gp2</code>|<code>gp3</code>\n               </p>\n            </li>\n            <li>\n               <p>Provisioned IOPS SSD: <code>io1</code>|<code>io2</code>\n               </p>\n            </li>\n            <li>\n               <p>Throughput Optimized HDD: <code>st1</code>\n               </p>\n            </li>\n            <li>\n               <p>Cold HDD: <code>sc1</code>\n               </p>\n            </li>\n            <li>\n               <p>Magnetic: <code>standard</code>\n               </p>\n               <note>\n                  <p>The magnetic volume type is not supported on Fargate.</p>\n               </note>\n            </li>\n         </ul>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:size_in_gi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'sizeInGiB', traits: {"smithy.api#documentation" => "<p>The size of the volume in GiB. You must specify either a volume size or a snapshot ID.\n\t\t\tIf you specify a snapshot ID, the snapshot size is used for the volume size by default.\n\t\t\tYou can optionally specify a volume size greater than or equal to the snapshot size.\n\t\t\tThis parameter maps 1:1 with the <code>Size</code> parameter of the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in the <i>Amazon EC2 API Reference</i>.</p>\n         <p>The following are the supported volume size values for each volume type.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp2</code> and <code>gp3</code>: 1-16,384</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code> and <code>io2</code>: 4-16,384</p>\n            </li>\n            <li>\n               <p>\n                  <code>st1</code> and <code>sc1</code>: 125-16,384</p>\n            </li>\n            <li>\n               <p>\n                  <code>standard</code>: 1-1,024</p>\n            </li>\n         </ul>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: EBSSnapshotId, location_name: 'snapshotId', traits: {"smithy.api#documentation" => "<p>The snapshot that Amazon ECS uses to create the volume. You must specify either a snapshot\n\t\t\tID or a volume size. This parameter maps 1:1 with the <code>SnapshotId</code> parameter\n\t\t\tof the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in\n\t\t\tthe <i>Amazon EC2 API Reference</i>.</p>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:volume_initialization_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'volumeInitializationRate', traits: {"smithy.api#documentation" => "<p>The rate, in MiB/s, at which data is fetched from a snapshot of an existing Amazon EBS\n\t\t\tvolume to create a new volume for attachment to the task. This property can be specified\n\t\t\tonly if you specify a <code>snapshotId</code>. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/initalize-volume.html\">Initialize Amazon EBS volumes</a> in the <i>Amazon EBS User\n\t\t\t\tGuide</i>.</p>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'iops', traits: {"smithy.api#documentation" => "<p>The number of I/O operations per second (IOPS). For <code>gp3</code>,\n\t\t\t<code>io1</code>, and <code>io2</code> volumes, this represents the number of IOPS that\n\t\t\tare provisioned for the volume. For <code>gp2</code> volumes, this represents the\n\t\t\tbaseline performance of the volume and the rate at which the volume accumulates I/O\n\t\t\tcredits for bursting.</p>\n         <p>The following are the supported values for each volume type.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp3</code>: 3,000 - 16,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 100 - 64,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io2</code>: 100 - 256,000 IOPS</p>\n            </li>\n         </ul>\n         <p>This parameter is required for <code>io1</code> and <code>io2</code> volume types. The\n\t\t\tdefault for <code>gp3</code> volumes is <code>3,000 IOPS</code>. This parameter is not\n\t\t\tsupported for <code>st1</code>, <code>sc1</code>, or <code>standard</code> volume\n\t\t\ttypes.</p>\n         <p>This parameter maps 1:1 with the <code>Iops</code> parameter of the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in the <i>Amazon EC2 API Reference</i>.</p>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'throughput', traits: {"smithy.api#documentation" => "<p>The throughput to provision for a volume, in MiB/s, with a maximum of 1,000 MiB/s.\n\t\t\tThis parameter maps 1:1 with the <code>Throughput</code> parameter of the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in the <i>Amazon EC2 API Reference</i>.</p>\n         <important>\n            <p>This parameter is only supported for the <code>gp3</code> volume type.</p>\n         </important>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: EBSTagSpecifications, location_name: 'tagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the volume. Amazon ECS applies service-managed tags by default. This\n\t\t\tparameter maps 1:1 with the <code>TagSpecifications.N</code> parameter of the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateVolume.html\">CreateVolume API</a> in the <i>Amazon EC2 API Reference</i>.</p>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IAMRoleArn, location_name: 'roleArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role to associate with this volume. This is the Amazon ECS\n\t\t\tinfrastructure IAM role that is used to manage your Amazon Web Services infrastructure. We recommend\n\t\t\tusing the Amazon ECS-managed <code>AmazonECSInfrastructureRolePolicyForVolumes</code> IAM\n\t\t\tpolicy with this role. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/infrastructure_IAM_role.html\">Amazon ECS\n\t\t\t\tinfrastructure IAM role</a> in the <i>Amazon ECS Developer\n\t\t\tGuide</i>.</p>", "smithy.api#required" => {}}))
    TaskManagedEBSVolumeConfiguration.add_member(:termination_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskManagedEBSVolumeTerminationPolicy, location_name: 'terminationPolicy', traits: {"smithy.api#documentation" => "<p>The termination policy for the volume when the task exits. This provides a way to\n\t\t\tcontrol whether Amazon ECS terminates the Amazon EBS volume when the task stops.</p>"}))
    TaskManagedEBSVolumeConfiguration.add_member(:filesystem_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskFilesystemType, location_name: 'filesystemType', traits: {"smithy.api#documentation" => "<p>The Linux filesystem type for the volume. For volumes created from a snapshot, you\n\t\t\tmust specify the same filesystem type that the volume was using when the snapshot was\n\t\t\tcreated. If there is a filesystem type mismatch, the task will fail to start.</p>\n         <p>The available filesystem types are\u2028 <code>ext3</code>, <code>ext4</code>, and\n\t\t\t\t<code>xfs</code>. If no value is specified, the <code>xfs</code> filesystem type is\n\t\t\tused by default.</p>"}))
    TaskManagedEBSVolumeConfiguration.type = Types::TaskManagedEBSVolumeConfiguration
    TaskManagedEBSVolumeTerminationPolicy.add_member(:delete_on_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'deleteOnTermination', traits: {"smithy.api#documentation" => "<p>Indicates whether the volume should be deleted on when the task stops. If a value of\n\t\t\t\t<code>true</code> is specified, \u2028Amazon ECS deletes the Amazon EBS volume on your behalf when\n\t\t\tthe task goes into the <code>STOPPED</code> state. If no value is specified, the\n\t\t\t\u2028default value is <code>true</code> is used. When set to <code>false</code>, Amazon ECS\n\t\t\tleaves the volume in your \u2028account.</p>", "smithy.api#required" => {}}))
    TaskManagedEBSVolumeTerminationPolicy.type = Types::TaskManagedEBSVolumeTerminationPolicy
