    TaskSet.add_member(:external_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'externalId', traits: {"smithy.api#documentation" => "<p>The external ID associated with the task set.</p>\n         <p>If an CodeDeploy deployment created a task set, the <code>externalId</code> parameter\n\t\t\tcontains the CodeDeploy deployment ID.</p>\n         <p>If a task set is created for an external deployment and is associated with a service\n\t\t\tdiscovery registry, the <code>externalId</code> parameter contains the\n\t\t\t\t<code>ECS_TASK_SET_EXTERNAL_ID</code> Cloud Map attribute.</p>"}))
    TaskSet.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status of the task set. The following describes each state.</p>\n         <dl>\n            <dt>PRIMARY</dt>\n            <dd>\n               <p>The task set is serving production traffic.</p>\n            </dd>\n            <dt>ACTIVE</dt>\n            <dd>\n               <p>The task set isn't serving production traffic.</p>\n            </dd>\n            <dt>DRAINING</dt>\n            <dd>\n               <p>The tasks in the task set are being stopped, and their corresponding\n\t\t\t\t\t\ttargets are being deregistered from their target group.</p>\n            </dd>\n         </dl>"}))
    TaskSet.add_member(:task_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'taskDefinition', traits: {"smithy.api#documentation" => "<p>The task definition that the task set is using.</p>"}))
