    UpdateContainerInstancesStateRequest.add_member(:container_instances, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'containerInstances', traits: {"smithy.api#documentation" => "<p>A list of up to 10 container instance IDs or full ARN entries.</p>", "smithy.api#required" => {}}))
    UpdateContainerInstancesStateRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerInstanceStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The container instance state to update the container instance with. The only valid\n\t\t\tvalues for this action are <code>ACTIVE</code> and <code>DRAINING</code>. A container\n\t\t\tinstance can only be updated to <code>DRAINING</code> status once it has reached an\n\t\t\t\t<code>ACTIVE</code> state. If a container instance is in <code>REGISTERING</code>,\n\t\t\t\t<code>DEREGISTERING</code>, or <code>REGISTRATION_FAILED</code> state you can\n\t\t\tdescribe the container instance but can't update the container instance state.</p>", "smithy.api#required" => {}}))
