    UpdateServicePrimaryTaskSetRequest.add_member(:service, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'service', traits: {"smithy.api#documentation" => "<p>The short name or full Amazon Resource Name (ARN) of the service that the task set exists in.</p>", "smithy.api#required" => {}}))
